Scoring Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(scoring_container, "Scoring Container") {
    Component(Model_Caching_Engine, "Model Caching Engine", "Local Container Memory Caching", "Caches model weights locally to meet strict sub-50ms latency requirements.")
    Component(Fraud_Evaluation_Engine, "Fraud Evaluation Engine", "AWS ECS Fargate Container", "Evaluates card-not-present payment authorizations to detect fraud.")
}

Rel(Fraud_Evaluation_Engine, Model_Caching_Engine, "Retrieves model weights from", "In-memory")

@enduml

Case Management Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Case Management Container", "Case Management Container") {
    Component(Case Router, "Case Router", "AWS ECS Fargate / Web Server", "Routes incoming case management traffic and handles HTTP requests.")
    Component(Case Data Handler, "Case Data Handler", "AWS ECS Fargate / Application Logic", "Processes and manages case data read and write operations.")
    Component(Audit Log Emitter, "Audit Log Emitter", "AWS SDK", "Emits signed audit logs to tamper-evident S3 storage.")
}

Rel(Case Router, Case Data Handler, "Forwards traffic and API requests", "Internal")
Rel(Case Data Handler, Audit Log Emitter, "Triggers emission of signed audit logs", "HTTPS")
@enduml

